fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let n = a.len();
    let mut result: Vec<i32> = Vec::with_capacity(n);

    let mut i = 0usize;
    while i < n {
        // Invariants maintained:
        // - 0 <= i <= n
        // - result.len() == i
        // - all elements in result are 1
        result.push(1);
        i += 1;
        // Termination measure: n - i decreases each iteration.
    }

    result
}